import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Field Groups in AL","description":"","frontmatter":{},"headers":[],"relativePath":"tables-fields-and-business-data/field-groups.md","filePath":"tables-fields-and-business-data/field-groups.md"}`),a={name:`tables-fields-and-business-data/field-groups.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="field-groups-in-al" tabindex="-1">Field Groups in AL <a class="header-anchor" href="#field-groups-in-al" aria-label="Permalink to “Field Groups in AL”">​</a></h1><p>Field groups let you <strong>group selected table fields for specific purposes in the Business Central user interface</strong>.</p><p>We&#39;ve already learned how to define fields in a table. For example, our <code>Course</code> table has <code>Course Code</code>, <code>Course Name</code>, <code>Description</code>, and <code>Price</code>.</p><p>But sometimes, Business Central needs to know which fields to use for a particular UI feature, rather than simply storing them in the table.</p><p>That&#39;s where field groups come in.</p><h2 id="the-main-field-group-you-ll-encounter-dropdown" tabindex="-1">The main field group you&#39;ll encounter: <code>DropDown</code> <a class="header-anchor" href="#the-main-field-group-you-ll-encounter-dropdown" aria-label="Permalink to “The main field group you&#39;ll encounter: DropDown”">​</a></h2><p>Suppose you have a list of courses and another page where users need to select a course from a lookup.</p><p>Instead of showing only the course code, you might want the lookup to display both the <strong>Course Code</strong> and <strong>Course Name</strong>.</p><p>A <code>DropDown</code> field group can specify which fields Business Central displays in supported dropdown and lookup experiences.</p><p>Business Central also supports a <code>Brick</code> field group, which is used for displaying records as tiles in supported list-page tile views. <a href="https://learn.microsoft.com/da-dk/dynamics365/business-central/dev-itpro/developer/devenv-field-groups" target="_blank" rel="noreferrer">Microsoft Learn</a></p><h2 id="add-a-dropdown-field-group-to-our-course-table" tabindex="-1">Add a <code>DropDown</code> field group to our Course table <a class="header-anchor" href="#add-a-dropdown-field-group-to-our-course-table" aria-label="Permalink to “Add a DropDown field group to our Course table”">​</a></h2><p>Let&#39;s use our existing <code>Course</code> table for a practical example.</p><p>Open <code>Course.Table.al</code> and add the following block <strong>after the <code>keys</code> block, but inside the table object</strong>:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fieldgroups</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    fieldgroup(DropDown; &quot;Course Code&quot;, &quot;Course Name&quot;)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Your table should now have this general structure:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>namespace LearningAl;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>table 50102 Course</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    Caption = &#39;Course&#39;;</span></span>
<span class="line"><span>    DataClassification = CustomerContent;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    fields</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        // Your existing fields remain here.</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    keys</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        key(PK; &quot;Course Code&quot;)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            Clustered = true;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    fieldgroups</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        fieldgroup(DropDown; &quot;Course Code&quot;, &quot;Course Name&quot;)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><strong>Keep your existing field definitions.</strong> The comments above simply indicate where they belong.</p><h3 id="understanding-the-syntax" tabindex="-1">Understanding the syntax <a class="header-anchor" href="#understanding-the-syntax" aria-label="Permalink to “Understanding the syntax”">​</a></h3><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fieldgroup(DropDown; &quot;Course Code&quot;, &quot;Course Name&quot;)</span></span></code></pre></div><ul><li><code>fieldgroups</code> introduces the field-group definitions.</li><li><code>fieldgroup</code> declares one group.</li><li><code>DropDown</code> identifies the type of group.</li><li><code>&quot;Course Code&quot;</code> and <code>&quot;Course Name&quot;</code> specify the fields to include.</li></ul><p>Notice that the field names are separated by <strong>commas</strong>, unlike the semicolons separating the arguments in our earlier <code>field(...)</code> declaration.</p><h2 id="what-happens-when-we-publish" tabindex="-1">What happens when we publish? <a class="header-anchor" href="#what-happens-when-we-publish" aria-label="Permalink to “What happens when we publish?”">​</a></h2><p>Save your file and press <strong>F5</strong>.</p><p>The field group tells Business Central which fields to use in supported dropdown and lookup experiences involving the Course table.</p><p>One important caveat: defining a field group doesn&#39;t automatically make every page display a dropdown containing those fields. The result depends on how the relevant page and lookup are implemented.</p><h2 id="what-about-field-groups-in-table-extensions" tabindex="-1">What about field groups in table extensions? <a class="header-anchor" href="#what-about-field-groups-in-table-extensions" aria-label="Permalink to “What about field groups in table extensions?”">​</a></h2><p>You can also extend field groups on existing tables.</p><p>For example, suppose we wanted to add our custom <code>Training Level</code> field to the Customer table&#39;s dropdown field group. We could extend <code>CustomerExt.TableExt.al</code> with:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fieldgroups</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    addlast(DropDown; &quot;Training Level&quot;)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Here, <code>addlast</code> adds the field to the end of the specified field group. The field must already exist on the table, and the target field group must support the operation. <a href="https://learn.microsoft.com/da-dk/dynamics365/business-central/dev-itpro/developer/devenv-field-groups" target="_blank" rel="noreferrer">Microsoft Learn</a></p><h2 id="key-takeaways" tabindex="-1">Key takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to “Key takeaways”">​</a></h2><ul><li><strong><code>DropDown</code></strong> specifies fields for supported dropdown and lookup experiences.</li><li><strong><code>Brick</code></strong> specifies fields used when displaying records as tiles in supported tile views.</li><li>Field groups are defined on tables or extended through table extensions.</li><li>Field groups influence how records are presented; they don&#39;t create new database fields.</li></ul><p><strong>Microsoft documentation:</strong> <a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-field-groups" target="_blank" rel="noreferrer">Field groups in Business Central</a></p><p>That&#39;s the core concept. We can now move on to <strong>Table Relationships (<code>TableRelation</code>)</strong>, where we&#39;ll learn how to connect fields across tables and restrict which records users can select.</p>`,34)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};